 public static final BlockPos P=new BlockPos(2400,205,8);public static volatile boolean ready;static ServerPlayer actor;static int stage,ticks;static long due;static Thaumatorium live;static ChestBlockEntity chest;static boolean deny,menuOpened;
 public static String mode(){return System.getProperty("thaumcraft.alchemyProbe","");}
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 @SubscribeEvent public static void deny(net.minecraftforge.event.level.BlockEvent.BreakEvent e){if(mode().startsWith("thaumatorium-")&&deny)e.setResult(net.minecraftforge.common.util.Result.DENY);}
 static void unlock(){var s=KnowledgeState.EMPTY;for(var e:ResearchCatalog.ENTRIES)s=s.stage(e.key(),999);KnowledgeStore.write(actor,s);}
 static void blueprint(ServerLevel l,BlockPos p){for(var at:BlockPos.betweenClosed(p.offset(-2,-2,-2),p.offset(2,3,2)))l.setBlockAndUpdate(at,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(p.below(2),Blocks.MAGMA_BLOCK.defaultBlockState());l.setBlockAndUpdate(p.below(),AlchemyContent.CRUCIBLE.get().defaultBlockState());for(var q:List.of(p,p.above()))l.setBlockAndUpdate(q,SimpleContent.BLOCKS.get("metal_alchemical").get().defaultBlockState());}
 static boolean salis(ServerLevel l,BlockPos p){actor.setPos(Vec3.atCenterOf(p));return actor.getMainHandItem().getItem().useOn(new UseOnContext(actor,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(p),Direction.UP,p,false)))==InteractionResult.SUCCESS;}
 static Thaumatorium form(ServerLevel l,BlockPos p){blueprint(l,p);actor.setYRot(180);actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(ArcaneContent.SALIS.get()));check(salis(l,p),"Salis formation failed");var m=(Thaumatorium)l.getBlockEntity(p);check(m.front()==Direction.SOUTH&&m.intact(),"Wrong assembled facing");return m;}
 static net.minecraft.world.item.crafting.RecipeHolder<?> recipe(Thaumatorium m,String path){return m.recipes().stream().filter(h->h.id().identifier().getPath().equals("crucible/"+path)).findFirst().orElseThrow();}
